using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
internal class CommandScript:IRunCommand{
 string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;
 bool Veg(Transform t){string s=P(t).ToLowerInvariant();return s.Contains("tree")||s.Contains("pine")||s.Contains("fir")||s.Contains("vegetation")||s.Contains("forest");}
 public void Execute(ExecutionResult result){var s=EditorSceneManager.OpenScene("Assets/Scenes/DragonIsle_Reference.unity",OpenSceneMode.Single);var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var reps=all.Where(t=>t.name.StartsWith("ApprovedReplacement_")).ToArray();int tilted=0,nullMat=0,noTex=0;float maxGround=0;var terrain=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Terrain>(true)).Single();
 foreach(var t in reps){var e=t.eulerAngles;float x=Mathf.Min(e.x,360-e.x),z=Mathf.Min(e.z,360-e.z);if(x>.1f||z>.1f)tilted++;foreach(var r in t.GetComponentsInChildren<Renderer>(true).Where(r=>r.enabled)){foreach(var m in r.sharedMaterials){if(!m){nullMat++;continue;}if(m.shader&&m.shader.name=="Standard"&&m.mainTexture==null)noTex++;} }var rs=t.GetComponentsInChildren<Renderer>(true).Where(r=>r.enabled).ToArray();if(rs.Length>0){Bounds b=rs[0].bounds;for(int i=1;i<rs.Length;i++)b.Encapsulate(rs[i].bounds);float g=terrain.SampleHeight(t.position)+terrain.transform.position.y;maxGround=Mathf.Max(maxGround,Mathf.Abs(b.min.y-g));}}
 int visibleLegacy=all.SelectMany(t=>t.GetComponents<Renderer>()).Count(r=>r.enabled&&r.gameObject.activeInHierarchy&&Veg(r.transform)&&!P(r.transform).Contains("ApprovedReplacement_"));
 Directory.CreateDirectory("Validation/FinalWorld");File.WriteAllText("Validation/FinalWorld/DragonIsle_final_audit.txt","approved_replacements="+reps.Length+"\nroot_tilted="+tilted+"\nnull_material_slots="+nullMat+"\nstandard_materials_without_maintexture="+noTex+"\nmax_ground_gap="+maxGround+"\nvisible_legacy_tree_renderers="+visibleLegacy+"\n");result.Log("Dragon reps="+reps.Length+" tilted="+tilted+" nullMat="+nullMat+" noTex="+noTex+" legacyVisible="+visibleLegacy+" ground="+maxGround);}
}